const familyRank = { projectile: 0, hazard: 1, specialist: 2, impact: 3, safeLane: -1 };
export function denseStrokeFamilyPresentation(input, reducedMotion = false, reducedFlash = false) { const crowd = clamp01(input.crowd), protectedStroke = input.family === 'safeLane' || input.bossProtected || (input.family === 'projectile' && input.critical), limit = input.strongStrokeLimit ?? (crowd >= .76 ? 1 : crowd >= .46 ? 2 : 3), strongStroke = protectedStroke || familyRank[input.family] < Math.max(1, Math.min(3, limit)), base = protectedStroke ? 1 : strongStroke ? Math.max(.9, 1 - crowd * .04) : input.family === 'hazard' ? .74 : input.family === 'specialist' ? .72 : input.family === 'impact' ? .68 : .78, accessibility = protectedStroke ? 1 : (reducedMotion ? .998 : 1) * (reducedFlash ? .998 : 1); return { canonicalStrokeWidthScale: 1, strokeWidthScale: base * accessibility, protectedStroke, strongStroke, presentationOnly: true }; }
export function denseStrokeBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), stress = clamp01(clamp01(input.crowd) * .78 + critical * .18 + (input.bossActive ? .04 : 0)), strongStrokeLimit = stress >= .76 ? 1 : stress >= .46 ? 2 : 3, laneReserve = input.safeLaneVisible ? .018 : 0, accessibility = (reducedMotion ? .998 : 1) * (reducedFlash ? .998 : 1); return { stress, strongStrokeLimit, canonicalStrokeWidthScale: 1, secondaryStrokeWidthScale: Math.max(.86, 1 - stress * .1 - laneReserve) * accessibility, safeLaneStrokeWidthScale: 1, presentationOnly: true }; }
